build), which writes through glibc-bindings' locked fprintf on C's
stderr, the crustify-campaign route; the sign-extended high byte of
C's %02x is not carried over.

The six functions C outside api.c calls (llhttp_execute,
llhttp_get_error_pos, llhttp_get_error_reason, llhttp_pause,
llhttp_resume, llhttp_resume_after_upgrade) are exported under the new
export feature ffi-export-deps-llhttp-api-c, off, each checked against
its raw binding. The raw bindings gain llhttp_lenient_flags and fifteen
functions; the 25 functions' pointer findings are submitted to the
ownership store. Four unit_priv, thirteen unit_pub, two ub_safe, four
equiv tests and three doctests. Proposals:
  1011 src/libgit2/deps/llhttp/api.rs
     2 src/libgit2/deps/llhttp/http.rs
  2641 src/libgit2/deps/llhttp/llhttp.rs
  3654 total
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#include "llhttp.h"

#define CALLBACK_MAYBE(PARSER, NAME)                                          \
  do {                                                                        \
    const llhttp_settings_t* settings;                                        \
    settings = (const llhttp_settings_t*) (PARSER)->settings;                 \
    if (settings == NULL || settings->NAME == NULL) {                         \
      err = 0;                                                                \
      break;                                                                  \
    }                                                                         \
    err = settings->NAME((PARSER));                                           \
  } while (0)

#define SPAN_CALLBACK_MAYBE(PARSER, NAME, START, LEN)                         \
  do {                                                                        \
    const llhttp_settings_t* settings;                                        \
    settings = (const llhttp_settings_t*) (PARSER)->settings;                 \
    if (settings == NULL || settings->NAME == NULL) {                         \
      err = 0;                                                                \
      break;                                                                  \
    }                                                                         \
    err = settings->NAME((PARSER), (START), (LEN));                           \
    if (err == -1) {                                                          \
      err = HPE_USER;                                                         \
      llhttp_set_error_reason((PARSER), "Span callback error in " #NAME);     \
    }                                                                         \
  } while (0)

void llhttp_init(llhttp_t* parser, llhttp_type_t type,
                 const llhttp_settings_t* settings) {
  llhttp__internal_init(parser);

  parser->type = type;
  parser->settings = (void*) settings;
}


