    macro_rules! set {
        ($i:expr, $get:ident, $set:ident,event) => {
            m.$set(Some(Callback::new::<Returning<R>>()));
        };
        ($i:expr, $get:ident, $set:ident,data) => {
            m.$set(Some(DataCallback::new::<Returning<R>>()));
        };
    }
    for_each_slot!(set);
    settings
}

