/// `ParserMut::finish` on `parser`, through `llhttp_finish`'s convention.
fn rust_finish(parser: &mut Parser) -> Step {
    let errno = match parser.as_mut().finish() {
        Ok(()) => sys::HPE_OK,
        Err(error) => error.code().cast_unsigned(),
    };
    (errno, LOG.take())
}

